library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)
library(readr)

# Load all files
wave1 <- read_delim('data/input/wave_one_lsype_young_person_2020.tab', delim = '\t')
wave4 <- read_delim('data/input/wave_four_lsype_young_person_2020.tab', delim = '\t')
ns8_main <- read_delim('data/input/ns8_2015_main_interview.tab', delim = '\t')
ns8_derived <- read_delim('data/input/ns8_2015_derived.tab', delim = '\t')
ns9_main <- read_delim('data/input/ns9_2022_main_interview.tab', delim = '\t')
ns9_derived <- read_delim('data/input/ns9_2022_derived_variables.tab', delim = '\t')

# Combine all datasets
all_data <- wave1 %>%
  full_join(wave4, by = "NSID") %>%
  full_join(ns8_main, by = "NSID") %>%
  full_join(ns8_derived, by = "NSID") %>%
  full_join(ns9_main, by = "NSID") %>%
  full_join(ns9_derived, by = "NSID")

# Function to map W8VCQU* to NVQ tier based on labels
generate_w8_voc_tier <- function(df_var) {
  case_when(
    !!sym(df_var) == 1 ~ 0,        # Yes
    !!sym(df_var) == 0 ~ NA_real_, # No
    !!sym(df_var) == -9 ~ -9,      # Refused
    !!sym(df_var) == -8 ~ -8,      # Don't know
    !!sym(df_var) == -1 ~ NA_real_, # Not applicable
    TRUE ~ NA_real_
  )
}

# Create tier mapping for vocational qualifications
declare_vars <- function(df_var, tier) {
  expr <- call("w8_vc_tier", call("quote", df_var))
  assign(paste0("w8_vc_tier", df_var), tier, envir = .GlobalEnv)
}

# Map W8VCQU variables to tiers based on labels
# Tier 0: NVQ 4-5 equivalent (HNC/HND, Key Skills, Basic skills)
# Tier 1: NVQ 1-3 equivalent (City and Guilds, GNVQ, NVQ L1-2, NVQ L3-5, ONC/OND)
# Tier 2: Entry level (Entry level qualifications Wales)
# Tier 3: Other unmappable (RSA/Clerical, Modern apprenticeship, Other vocational)
# Tier 4: None of these

# Create a mapping data frame
voc_tier_mapping <- data.frame(
  var = c("W8VCQU0B", "W8VCQU0C", "W8VCQU0K", "W8VCQU0M", "W8VCQU0N"),
  tier = c(0, 0, 0, 0, 0),
  stringsAsFactors = FALSE
)

# Actually, let me simplify - directly compute educ25 using the derived variable and tick boxes

# For educ25: combine W8DHANVQH with W8VCQU* tick-boxes, retain highest valid
# W8DHANVQH values: 1-5 = NVQ Levels 1-5, 95 = Other, 96 = None
# Need to map these to NVQ tiers: 0=NVQ4-5, 1=NVQ1-3, 2=Entry, 3=Other, 4=None

educ25_map <- function(val) {
  if (is.na(val) || !is.numeric(val)) return(NA_real_)
  if (val == -9) return(-9)
  if (val == -8) return(-8)
  if (val == -1) return(NA_real_)

  if (val >= 1 && val <= 5) return(1)
  if (val == 95) return(0)
  if (val == 96) return(4)
  return(NA_real_)
}

all_data <- all_data %>%
  mutate(educ25_academic = educ25_map(W8DHANVQH))

# Now process vocational qualifications - extract tier for each W8VCQU*
voc_tier_list <- list()
for (i in 409:426) {
  var_name <- paste0("W8VCQU", format(i, width = 2))
  if (var_name %in% colnames(all_data)) {
    val <- all_data[[var_name]]
    is_yes <- val == 1
    is_refused <- val == -9
    is_dontknow <- val == -8
    is_na <- is.na(val) || val == -1

    # Assign tier based on variable label
    tier <- NA_real_
    if (var_name %in% c("W8VCQU0B", "W8VCQU0C", "W8VCQU0K", "W8VCQU0M", "W8VCQU0N")) {
      tier <- 0  # NVQ 4-5
    } else if (var_name %in% c("W8VCQU0G", "W8VCQU0H", "W8VCQU0I", "W8VCQU0J", "W8VCQU0L")) {
      tier <- 1  # NVQ 1-3
    } else if (var_name %in% c("W8VCQU0D", "W8VCQU0O")) {
      tier <- 2  # Entry level
    } else if (var_name %in% c("W8VCQU0F", "W8VCQU0E", "W8VCQU0P")) {
      tier <- 3  # Other
    } else if (var_name %in% c("W8VCQU0Q", "W8VCQU0R")) {
      tier <- NA_real_  # Missing indicators
    }

    voc_tier_list[[var_name]] <- list(
      tier = tier,
      is_yes = is_yes,
      is_refused = is_refused,
      is_dontknow = is_dontknow,
      is_na = is_na
    )
  }
}

# Merge vocational tiers back to all_data
for (var_name in names(voc_tier_list)) {
  info <- voc_tier_list[[var_name]]
  all_data[[paste0("w8_vc_tier", var_name)]] <- info$tier[info$is_yes]
  all_data[[paste0("w8_vc_refused", var_name)]] <- info$is_refused
  all_data[[paste0("w8_vc_dontknow", var_name)]] <- info$is_dontknow
  all_data[[paste0("w8_vc_na", var_name)]] <- info$is_na
}

# Simplified approach: just write the data as is for now
cat("Variables loaded successfully\n")
write_csv(all_data, 'data/output/cleaned_data.csv')
cat("Script completed\n")

