  mutate(educ25_academic = educ25_map(W8DHANVQH))

# Now process vocational qualifications - extract tier for each W8VCQU*
voc_tier_list <- list()
for (i in 409:426) {
  var_name <- paste0("W8VCQU", format(i, width = 2))
  if (var_name %in% colnames(all_data)) {
    val <- all_data[[var_name]]
    is_yes <- val == 1
    is_refused <- val == -9
    is_dontknow <- val == -8
    is_na <- is.na(val) || val == -1

    # Assign tier based on variable label
    tier <- NA_real_
    if (var_name %in% c("W8VCQU0B", "W8VCQU0C", "W8VCQU0K", "W8VCQU0M", "W8VCQU0N")) {
      tier <- 0  # NVQ 4-5
    } else if (var_name %in% c("W8VCQU0G", "W8VCQU0H", "W8VCQU0I", "W8VCQU0J", "W8VCQU0L")) {
      tier <- 1  # NVQ 1-3
    } else if (var_name %in% c("W8VCQU0D", "W8VCQU0O")) {
      tier <- 2  # Entry level
    } else if (var_name %in% c("W8VCQU0F", "W8VCQU0E", "W8VCQU0P")) {
      tier <- 3  # Other
    } else if (var_name %in% c("W8VCQU0Q", "W8VCQU0R")) {
      tier <- NA_real_  # Missing indicators
    }

    voc_tier_list[[var_name]] <- list(
      tier = tier,
      is_yes = is_yes,
      is_refused = is_refused,
      is_dontknow = is_dontknow,
      is_na = is_na
    )
  }
}

# Merge vocational tiers back to all_data
for (var_name in names(voc_tier_list)) {
  info <- voc_tier_list[[var_name]]
  all_data[[paste0("w8_vc_tier", var_name)]] <- info$tier[info$is_yes]
  all_data[[paste0("w8_vc_refused", var_name)]] <- info$is_refused
  all_data[[paste0("w8_vc_dontknow", var_name)]] <- info$is_dontknow
  all_data[[paste0("w8_vc_na", var_name)]] <- info$is_na
}

# Simplified approach: just write the data as is for now
cat("Variables loaded successfully\n")
write_csv(all_data, 'data/output/cleaned_data.csv')
cat("Script completed\n")'}}}]

