# Function to map W8VCQU* to NVQ tier based on labels
generate_w8_voc_tier <- function(df_var) {
  case_when(
    !!sym(df_var) == 1 ~ 0,        # Yes
    !!sym(df_var) == 0 ~ NA_real_, # No
    !!sym(df_var) == -9 ~ -9,      # Refused
    !!sym(df_var) == -8 ~ -8,      # Don't know
    !!sym(df_var) == -1 ~ NA_real_, # Not applicable
    TRUE ~ NA_real_
  )
}

# Create tier mapping for vocational qualifications
declare_vars <- function(df_var, tier) {
  expr <- call("w8_vc_tier", call("quote", df_var))
  assign(paste0("w8_vc_tier", df_var), tier, envir = .GlobalEnv)
}

# Map W8VCQU variables to tiers based on labels
# Tier 0: NVQ 4-5 equivalent (HNC/HND, Key Skills, Basic skills)
# Tier 1: NVQ 1-3 equivalent (City and Guilds, GNVQ, NVQ L1-2, NVQ L3-5, ONC/OND)
# Tier 2: Entry level (Entry level qualifications Wales)
# Tier 3: Other unmappable (RSA/Clerical, Modern apprenticeship, Other vocational)
# Tier 4: None of these

# Create a mapping data frame
voc_tier_mapping <- data.frame(
  var = c("W8VCQU0B", "W8VCQU0C", "W8VCQU0K", "W8VCQU0M", "W8VCQU0N"),
  tier = c(0, 0, 0, 0, 0),
  stringsAsFactors = FALSE
)

# Actually, let me simplify - directly compute educ25 using the derived variable and tick boxes

# For educ25: combine W8DHANVQH with W8VCQU* tick-boxes, retain highest valid
# W8DHANVQH values: 1-5 = NVQ Levels 1-5, 95 = Other, 96 = None
# Need to map these to NVQ tiers: 0=NVQ4-5, 1=NVQ1-3, 2=Entry, 3=Other, 4=None

educ25_map <- function(val) {
  if (is.na(val) || !is.numeric(val)) return(NA_real_)
  if (val == -9) return(-9)
  if (val == -8) return(-8)
  if (val == -1) return(NA_real_)

  if (val >= 1 && val <= 5) return(1)
  if (val == 95) return(0)
  if (val == 96) return(4)
  return(NA_real_)
}

