  var_name <- paste0("W8VCQU", format(i, width = 2))
  if (var_name %in% colnames(all_data)) {
    val <- all_data[[var_name]]
    is_yes <- val == 1
    is_refused <- val == -9
    is_dontknow <- val == -8
    is_na <- is.na(val) || val == -1

    # Assign tier based on variable label
    tier <- NA_real_
