  if (v == -9) return(-9)
  if (v == -8) return(-8)
  if (v == -1) return(NA_real_)
  if (v >= 1 && v <= 5) return(1)
  if (v == 95) return(0)
  if (v == 96) return(4)
  return(NA_real_)
}

